import os
class PathCompat(object):
    def __init__(self,path):self.path=path
    def __str__(self):return self.path
    def __div__(self,other):return PathCompat(os.path.join(self.path,other))
    def __truediv__(self,other):return self.__div__(other)
    def is_symlink(self):return os.path.islink(self.path)
    def resolve(self):return os.path.realpath(self.path)
    def read_bytes(self):
        with open(self.path,'rb') as stream:return stream.read()
    def write_bytes(self,data):
        with open(self.path,'wb') as stream:return stream.write(data)

