argv=[str(value) for value in payload['plugins']]+['-rA','-v']
print('>>>>> Start Test Output')
try:
    exit_code=pytest.main(argv,plugins=[recorder])
finally:
    stop_function_servers()
    print('P07_FUNCTION_SERVERS_STOPPED=1')
    sys.stdout.flush()
print('P07_TARGET_RESULT='+json.dumps({'version_info':list(sys.version_info[:3]),'prefix':sys.prefix,'executable':sys.executable,
    'pytest_module':pytest.__file__,'pytest_version':pytest.__version__,'requests_module':requests.__file__,
    'argv':argv,'plugins':recorder.plugins,'collection':recorder.collected,'reports':recorder.reports,'finished':recorder.finished,'exit':recorder.exit},sort_keys=True))
print('P07_TEST_EXIT='+str(exit_code))
print('>>>>> End Test Output')
raise SystemExit(exit_code)
